#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
#
# Hahakigami Lite: Apple Developer and App Store Connect setup (issue #96, ADR 0007).
# Run from the repository root:  scripts/appstore_lite_wizard.sh
# Records non-secret identifiers only, in .appstore-lite.env (gitignored).
# Never asks for an Apple ID password, App Store Connect API key or app-specific password.

BUNDLE_ID="app.hahakigami.lite"
APP_NAME="Hahakigami Lite"
REPO_URL="https://github.com/kitsupanic/Hahakigami"
SUPPORT_URL="$REPO_URL/issues"
PRIVACY_URL="$REPO_URL/blob/main/PRIVACY.md"

# identity_sha1 PATTERN [POLICY...]: SHA-1 of each valid identity whose name starts with PATTERN (a regex; use a|b for alternatives).
identity_sha1() {
  local pattern="$1"; shift
  security find-identity -v "$@" 2>/dev/null | grep -E "\"(${pattern}): " | awk '{print $2}' || true
}

# copy TEXT: put TEXT on the clipboard and show it.
copy() {
  printf '%s' "$1" | pbcopy
  printf '  %s✓ copied to the clipboard:%s\n' "$GREEN" "$RESET"
  printf '%s\n' "$1" | sed 's/^/    /'
}

wait_for_identity() {
  local label="$1" pattern="$2" sha count
  while :; do
    sha=$(identity_sha1 "$pattern")
    count=$(printf '%s' "$sha" | grep -c . || true)
    if (( count == 1 )); then printf '%s' "$sha"; return; fi
    if (( count > 1 )); then
      warn "found $count valid '$pattern' identities. Keep one (revoke the extras in Manage Certificates) or pick by SHA-1:" >&2
      printf '%s\n' "$sha" | sed 's/^/    /' >&2
      while :; do
        ask PICKED "SHA-1 to use:" >&2 || return 1
        PICKED=$(printf '%s' "$PICKED" | tr '[:lower:]' '[:upper:]')
        if printf '%s\n' "$sha" | grep -qxF "$PICKED"; then printf '%s' "$PICKED"; return; fi
        warn "'$PICKED' is not one of the SHA-1 values listed above." >&2
      done
    fi
    warn "no valid $label identity in your keychain yet." >&2
    pause "Create it as described above, then press Enter to check again." >&2
  done
}

run_wizard() {

TOTAL_STAGES=13
ENV_FILE=".appstore-lite.env"

banner "Hahakigami Lite: App Store setup (#96)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before you start"
say "You need:"
step "A paid Apple Developer Program membership (Account Holder or Admin role)."
step "Xcode, signed in to that Apple Account (Xcode → Settings → Accounts)."
step "This Mac's login keychain unlocked. Certificates are created in it; nothing is exported."
note "This wizard never asks for passwords or API keys. It saves only identifiers to $ENV_FILE."
[[ -f src-tauri/tauri.lite.conf.json ]] || { warn "Run this from the Hahakigami repository root."; exit 1; }
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Apple Distribution certificate"
say "Signs the Lite app for the Mac App Store."
step "Open Xcode → Settings… → Accounts, select your team, click Manage Certificates…"
step "Click + (bottom left) → Apple Distribution. Xcode creates the key in your keychain."
note "Skip this if the list already shows a valid Apple Distribution certificate."
pause "Done? Press Enter to check the keychain."
DIST_SHA1=$(wait_for_identity "Apple Distribution" "Apple Distribution")
write_env APPLE_DISTRIBUTION_SHA1 "$DIST_SHA1"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Mac Installer Distribution certificate"
say "Signs the .pkg that Transporter uploads."
step "In the same Manage Certificates sheet: + → Mac Installer Distribution."
pause "Done? Press Enter to check the keychain."
note "Older accounts show the same certificate as '3rd Party Mac Developer Installer'; that name works too."
INSTALLER_SHA1=$(wait_for_identity "Mac Installer Distribution" "Mac Installer Distribution|3rd Party Mac Developer Installer")
write_env INSTALLER_SHA1 "$INSTALLER_SHA1"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Team ID"
DETECTED_TEAM=$(security find-certificate -a -Z -p 2>/dev/null \
  | awk -v sha="$APPLE_DISTRIBUTION_SHA1" '/^SHA-1 hash:/{keep=($3==sha)} keep' \
  | openssl x509 -noout -subject 2>/dev/null | sed -nE 's/.*OU ?= ?([A-Z0-9]{10}).*/\1/p' | head -n1 || true)
if [[ -n "$DETECTED_TEAM" ]]; then
  say "Your Apple Distribution certificate belongs to team $DETECTED_TEAM."
  if confirm "Use $DETECTED_TEAM as the Team ID?"; then write_env TEAM_ID "$DETECTED_TEAM"; fi
fi
if [[ -z "${TEAM_ID:-}" ]]; then
  open_url "https://developer.apple.com/account#MembershipDetailsCard"
  step "Copy the Team ID (10 characters) from Membership details."
  ask TEAM_ID "Team ID:"
  [[ "$TEAM_ID" =~ ^[A-Z0-9]{10}$ ]] || { warn "That doesn't look like a Team ID."; exit 1; }
  write_env TEAM_ID "$TEAM_ID"
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Register the App ID"
open_url "https://developer.apple.com/account/resources/identifiers/add/bundleId"
step "Choose App IDs → Continue → App → Continue."
step "Description: $APP_NAME"
step "Bundle ID: Explicit, $BUNDLE_ID"
step "Platform: macOS. Leave every capability unticked (the App Sandbox is an entitlement, not a capability here)."
step "Continue → Register."
note "If it says the identifier is taken by your team, it's already registered: carry on."
copy "$BUNDLE_ID"
pause "Registered? Press Enter."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Mac App Store provisioning profile"
open_url "https://developer.apple.com/account/resources/profiles/add"
step "Distribution → Mac App Store Connect → Continue."
step "App ID: $APP_NAME ($TEAM_ID.$BUNDLE_ID) → Continue."
step "Certificate: the Apple Distribution certificate from stage 2 → Continue."
step "Profile name: Hahakigami Lite Mac App Store → Generate → Download."
note "Keep the file outside this repository, e.g. ~/Documents/Apple/. Don't double-click it."
while :; do
  ask PROVISIONING_PROFILE "Path to the downloaded .provisionprofile:"
  PROVISIONING_PROFILE="${PROVISIONING_PROFILE/#\~/$HOME}"
  [[ -f "$PROVISIONING_PROFILE" ]] || { warn "No file at that path."; continue; }
  case "$(cd "$(dirname "$PROVISIONING_PROFILE")" && pwd)/" in
    "$PWD"/*) warn "That's inside the repository. Move it out first."; continue ;;
  esac
  PLIST=$(mktemp); security cms -D -i "$PROVISIONING_PROFILE" > "$PLIST" 2>/dev/null || { warn "Not a provisioning profile."; rm -f "$PLIST"; continue; }
  APP_IDENT=$(/usr/libexec/PlistBuddy -c 'Print :Entitlements:com.apple.application-identifier' "$PLIST" 2>/dev/null || true)
  rm -f "$PLIST"
  if [[ "$APP_IDENT" == "$TEAM_ID.$BUNDLE_ID" ]]; then
    printf '  %s✓ profile is for %s%s\n' "$GREEN" "$APP_IDENT" "$RESET"; break
  fi
  warn "This profile is for '${APP_IDENT:-unknown}', not $TEAM_ID.$BUNDLE_ID."
done
write_env PROVISIONING_PROFILE "$PROVISIONING_PROFILE"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Create the App Store Connect record"
open_url "https://appstoreconnect.apple.com/apps"
step "Click + → New App."
step "Platforms: macOS.   Name: $APP_NAME   Primary language: English (U.S.)"
step "Bundle ID: $APP_NAME - $BUNDLE_ID   SKU: hahakigami-lite   User access: Full Access"
step "Click Create."
note "If the name is taken, stop here and decide on another name before continuing."
copy "$APP_NAME"
pause "Created? Press Enter."
step "Open App Information (left sidebar, under General) and copy the Apple ID (a number)."
ask APP_STORE_APPLE_ID "App Store Apple ID:"
[[ "$APP_STORE_APPLE_ID" =~ ^[0-9]+$ ]] || warn "Expected digits only; check it later in $ENV_FILE."
write_env APP_STORE_APPLE_ID "$APP_STORE_APPLE_ID"
write_env SKU "hahakigami-lite"
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "App information: category, age rating, subtitle"
say "Still on App Information:"
step "Subtitle (English): Disk space analyzer"
copy "Disk space analyzer"
step "Category: Primary Utilities. Secondary: none."
step "Content Rights: No, it does not contain, show or access third-party content."
step "Age Rating → Set Up Age Ratings: answer None / No to every question → Done. Expect the lowest rating (4+)."
step "Click Save (top right)."
pause "Saved? Press Enter."

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Price: Free"
open_url "https://appstoreconnect.apple.com/apps/$APP_STORE_APPLE_ID"
step "Sidebar: Pricing and Availability → Price Schedule → Add Pricing → Base country: United States, Price: Free (0.00) → Confirm."
step "Availability: all countries and regions (the default) is fine."
step "Leave 'Make this app available on Apple Vision Pro / iPhone and iPad' off: Lite is macOS only."
pause "Free and saved? Press Enter."

# ── 10 ────────────────────────────────────────────────────────────────────
stage "App Privacy: Data Not Collected"
warn "PRIVACY.md must be on the main branch first, or this URL is a 404 (merge PR #100)."
open_url "$PRIVACY_URL"
pause "Does the privacy page load? Press Enter."
open_url "https://appstoreconnect.apple.com/apps/$APP_STORE_APPLE_ID"
step "Sidebar: App Privacy. Privacy Policy URL: Edit → paste → Save."
copy "$PRIVACY_URL"
step "Data Types: Get Started → 'No, we do not collect data from this app' → Save."
step "Click Publish (top right) and confirm."
note "Lite has the network.client entitlement only so WebKit renders; it sends nothing (ADR 0007)."
pause "Published? Press Enter."

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Version page: description and keywords"
open_url "https://appstoreconnect.apple.com/apps/$APP_STORE_APPLE_ID"
say "Sidebar: macOS App → 1.0 Prepare for Submission. Each field is copied for you in turn."
copy "See what fills your Mac. Scan a disk or folder, explore it as a size-sorted list, treemap or sunburst, and move what you no longer need to the Trash."
pause "Paste into Promotional Text, then press Enter for the description."
copy "$(cat <<'DESC'
Hahakigami Lite shows what is using space on your Mac, and helps you clear it out carefully.

SCAN ANY DISK OR FOLDER
Allow access to your startup disk once, and Hahakigami Lite can scan it and every attached disk. Or scan just one folder. Access is remembered across launches, and you can remove it any time.

SEE WHERE THE SPACE GOES
• A size-sorted folder list, a treemap and a sunburst chart
• Sizes are on disk; hard links and APFS clones are counted once
• Search every name in a scan, filter by file category and size
• A breakdown of usage by file type
• Quick Look previews and Reveal in Finder

CLEAN UP CAREFULLY
Add items to a cleanup queue that survives restarts, review the exact paths, then move them to the Trash. Nothing is ever deleted permanently.

FAST
Rescans of folders reuse what hasn't changed.

PRIVATE
No accounts, analytics or ads. Scanning reads file metadata only, never file contents, and nothing leaves your Mac.

For the widest view of your startup disk, grant Full Disk Access in System Settings. The app shows whether it's on.

Hahakigami is free and open source: github.com/kitsupanic/Hahakigami
DESC
)"
pause "Paste into Description, then press Enter for keywords."
copy "disk,space,storage,analyzer,usage,cleaner,treemap,sunburst,folder,size,files,cleanup,trash"
pause "Paste into Keywords, then press Enter for the URLs."
step "Support URL: $SUPPORT_URL"
copy "$SUPPORT_URL"
step "Marketing URL: $REPO_URL (optional)"
step "Copyright: $(date +%Y) <your name or the project's legal owner>"
step "Click Save (top right)."
pause "Saved? Press Enter."

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Screenshots"
say "Mac screenshots must be exactly 1280×800, 1440×900, 2560×1600 or 2880×1800 (16:10), 1 to 10 of them."
step "Open Hahakigami Lite (pnpm desktop:build --lite), scan Macintosh HD, then capture e.g.:"
note "   1. Sunburst of Macintosh HD   2. Treemap   3. File types   4. Search results   5. Cleanup queue review"
step "On a 16:10 display: zoom the window to fill the screen, Cmd-Shift-3 for the full screen."
note "Avoid personal file names in shots; scan a demo folder if needed. They can be refreshed before #98."
ask SCREENSHOT_DIR "Folder with the screenshots (Enter to skip for now):" || true
if [[ -n "${SCREENSHOT_DIR:-}" ]]; then
  SCREENSHOT_DIR="${SCREENSHOT_DIR/#\~/$HOME}"
  ok=0; bad=0
  for f in "$SCREENSHOT_DIR"/*.png "$SCREENSHOT_DIR"/*.jpg "$SCREENSHOT_DIR"/*.jpeg; do
    [[ -f "$f" ]] || continue
    size=$(sips -g pixelWidth -g pixelHeight "$f" 2>/dev/null | awk '/pixel/{printf "%s ", $2}')
    case "$size" in
      "1280 800 "|"1440 900 "|"2560 1600 "|"2880 1800 ") ok=$((ok+1)); note "✓ $(basename "$f") ($size)";;
      *) bad=$((bad+1)); warn "$(basename "$f") is ${size:-unreadable}: resize, e.g. sips -z 1800 2880 \"$f\" (only if already 16:10)";;
    esac
  done
  say "$ok usable, $bad to fix."
  write_env SCREENSHOT_DIR "$SCREENSHOT_DIR"
  step "Drag the usable ones into the macOS Previews and Screenshots box on the version page → Save."
else
  SKIPPED+=("Screenshots on the macOS version page (re-run the wizard or upload before #98)")
fi
pause

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Check"
security find-identity -v | grep -qF "$APPLE_DISTRIBUTION_SHA1" && note "✓ Apple Distribution identity is valid" || warn "Apple Distribution identity not found"
security find-identity -v | grep -qF "$INSTALLER_SHA1" && note "✓ Installer identity is valid" || warn "Installer identity not found"
say "In App Store Connect, confirm: bundle ID $BUNDLE_ID, price Free, App Privacy 'Data Not Collected' (published), an age rating, description and keywords saved."
note "Next (#98): pnpm desktop:build --lite --release --provisioning-profile \"$PROVISIONING_PROFILE\""
note "App Review contact details and the build are filled in at submission (#98)."
pause "All good? Press Enter to finish."

finish
}

run_wizard "$@"; exit
